local UIFishPoolCreelSelectNode = Class("UIFishPoolCreelSelectNode")
function UIFishPoolCreelSelectNode:__init() 
    self._data = nil
    self._curNum = 1         --当前选择的数量
end

function UIFishPoolCreelSelectNode:__delete()
    self._data = nil
    self._curNum = nil         --当前选择的数量
end

function UIFishPoolCreelSelectNode:Awake()    
end

function UIFishPoolCreelSelectNode:Start()
    SetButtonAction(self.BtnMax, Bind(self, self.OnBtnMax))
    SetButtonAction(self.BtnMin, Bind(self, self.OnBtnMin))
    SetButtonAction(self.BtnAdd, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.BtnReduce, Bind(self, self.OnBtnReduce))
    self.InputFieldNumber.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 1 then
            self._curNum = 1
        elseif num >= checkNumber(self._data.num) then
            self._curNum = checkNumber(self._data.num)
        else
            self._curNum = num    
        end
        self:RefreshSelectNum()
    end)

    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnMake))
    SetButtonAction(self.SellFontStyleButton, Bind(self, self.OnBtnSell))
end

function UIFishPoolCreelSelectNode:Refresh(data)
    if not data then
        return 
    end
    self._data = data
    self._curNum = 1   
    self:FillSelf()
end

function UIFishPoolCreelSelectNode:FillSelf()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.fishId)
    if vo then
        CfUtils.FillText(self.TextTitle, vo.name)
        CfUtils.FillImage(self.ImgFishIcon, vo.photoPath)
        CfUtils.FillImage(self.ImgRare, GoodsUtils.GetGoodsExhibitBgByQualityType(vo.quality))
    end
    --CfUtils.FillText(self.TextTitle, vo.name)
    self:RefreshSelectNum()

    local path
    vo = FishingUtils.GetFishingSpeciesVo(self._data.fishId)
    if vo then
        path = GoodsConfMgr:GetInstance():GetPhotoPathById(vo.baitMaking)
        CfUtils.FillImage(self.ConsumeImage, path)
    end
    --path = GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.GoldId)
    --CfUtils.FillImage(self.SellImage, path)
    CfUtils.FillText(self.TextState1, localize("获得"))
    CfUtils.FillText(self.TextState2, localize("获得"))
    CfUtils.FillText(self.TextNumber, self._data.num)

    --self:RefreshMakeInfo()
    self:RefreshSellInfo()

    local isCanBait = checkNumber(vo.baitMaking) > 0
    local isCanGetSpecialBait = checkNumber(vo.specialBait) > 0 
    KTool.SetActive(self.Enable, isCanBait or isCanGetSpecialBait)
    KTool.SetActive(self.Disable, not (isCanBait or isCanGetSpecialBait))

    KTool.SetActive(self.BtnIconLeft, isCanBait)
    KTool.SetActive(self.BtnIconRight, isCanGetSpecialBait)
    if isCanBait then
        local baitVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.baitMaking)
        if baitVo then
            CfUtils.FillImage(self.BtnIconLeft.transform:Find("ImgIcon"), baitVo.photoPath)
            SetButtonAction(self.BtnIconLeft, function()
                GameUtils.ShowCommonGoodsTipsBoard(self.BtnIconLeft, vo.baitMaking, false)
            end)
        end
    else
        SetButtonAction(self.BtnIconLeft, function()
            
        end)
    end

    if isCanGetSpecialBait then
        local baitVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.specialBait)
        if baitVo then
            CfUtils.FillImage(self.BtnIconRight.transform:Find("ImgIcon"), baitVo.photoPath)
            SetButtonAction(self.BtnIconRight, function()
                GameUtils.ShowCommonGoodsTipsBoard(self.BtnIconLeft, vo.specialBait, false)
            end)
        end
    else
        SetButtonAction(self.BtnIconRight, function()
            
        end)
    end
end

function UIFishPoolCreelSelectNode:RefreshSelectNum()
    self.InputFieldNumber.text = self._curNum
    --self:RefreshMakeInfo()
    self:RefreshSellInfo()
end

--刷新制作信息
function UIFishPoolCreelSelectNode:RefreshMakeInfo()
    local vo = FishingUtils.GetFishingSpeciesVo(self._data.fishId)
    if vo then
        local num = checkNumber(vo.baitNum) * self._curNum
        CfUtils.FillText(self.ConsumeText, "X"..num)
    end
end

--刷新出售信息
function UIFishPoolCreelSelectNode:RefreshSellInfo()
    local vo = FishingUtils.GetFishingSpeciesVo(self._data.fishId)
    if vo then
        --local num = checkNumber(vo.price) * self._curNum
        --CfUtils.FillText(self.TextSell, "X"..num)
        local ratingVo = FishingUtils.GetFishingRatingVo(self._data.rating)
        print(vo.price, (1 + ratingVo.priceAddition))
        CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.FishCurrency))
        CfUtils.FillText(self.Text2, math.floor(vo.price * (1 + ratingVo.priceAddition)) * self._curNum)
        --CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, Constants.Currency.FishCurrency, math.floor(vo.price * (1 + ratingVo.priceAddition)) * self._curNum, true)
    end
end

--最多
function UIFishPoolCreelSelectNode:OnBtnMax()
    self._curNum = checkNumber(self._data.num)
    self:RefreshSelectNum()
end

--最少
function UIFishPoolCreelSelectNode:OnBtnMin()
    self._curNum = 1
    self:RefreshSelectNum()
end

--增加
function UIFishPoolCreelSelectNode:OnBtnAdd()
    if self._curNum >= checkNumber(self._data.num) then
        GameUtils.Toast(localize("已经最大数量了"))
        return 
    end
    self._curNum = self._curNum + 1
    self:RefreshSelectNum()
end

--减少
function UIFishPoolCreelSelectNode:OnBtnReduce()
    if self._curNum <= 1 then
        GameUtils.Toast(localize("已经最低数量了"))
        return 
    end
    self._curNum = self._curNum - 1
    self:RefreshSelectNum()
end

--制作
function UIFishPoolCreelSelectNode:OnBtnMake()
    local isCanMakeBait = FishingUtils.IsCanMakeBait(self._data.fishId)
    if not isCanMakeBait then
        GameUtils.Toast(localize("该鱼种无法制作鱼饵"))
        return
    end
    fishingComponent:FishingMakeReq({
        {
            fishId = checkNumber(self._data.fishId),
            rating = checkNumber(self._data.rating),
            num = self._curNum
        }
    })
end

--出售
function UIFishPoolCreelSelectNode:OnBtnSell()
    fishingComponent:FishingSaleReq({
        {
            fishId = checkNumber(self._data.fishId),
            rating = checkNumber(self._data.rating),
            num = self._curNum
        }
    })
end

function UIFishPoolCreelSelectNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolCreelSelectNode
